def decide(recipient_reputation, round_num, my_history):
    # Base threshold increases linearly with round, capped after round 30
    base_threshold = 0.3 + 0.02 * min(round_num - 1, 30)
    # Adjust based on own cooperation history (indirect, not direct reciprocity)
    if len(my_history) > 0:
        coop_frac = sum(my_history) / len(my_history)
        if coop_frac > 0.5:
            # If we have cooperated more than half the time, become more generous
            generosity = 0.2 * (coop_frac - 0.5)
            threshold = base_threshold * (1 - generosity)
        else:
            threshold = base_threshold
    else:
        threshold = base_threshold
    return recipient_reputation >= threshold
